<section class="lp-section lp-inner-content"><div class="lp-container">
<?php if($codes):?><div class="lp-gift-grid"><?php foreach($codes as $index=>$gift):?><article class="lp-gift-card" data-landing-reveal><div class="lp-gift-visual tone-<?=($index%3)+1?>"><span>✦</span><b>QUÀ<br>KPAH</b></div><div class="lp-gift-copy"><div class="lp-gift-meta"><span>Giftcode công khai</span><small>Còn <?=number_format((int)$gift['limit_use'],0,',','.')?> lượt</small></div><h3><?=kp_e($gift['title']!==''?$gift['title']:'Quà tặng nhà phiêu lưu')?></h3><p><?=kp_e($gift['description']!==''?$gift['description']:'Nhập mã trong game để nhận phần thưởng.')?></p><div class="lp-gift-rewards"><?php if((int)$gift['xu']>0):?><span><?=number_format((int)$gift['xu'],0,',','.')?> Xu</span><?php endif;?><?php if((int)$gift['luong']>0):?><span><?=number_format((int)$gift['luong'],0,',','.')?> Lượng</span><?php endif;?><?php if((int)$gift['luongLock']>0):?><span><?=number_format((int)$gift['luongLock'],0,',','.')?> Lượng khóa</span><?php endif;?><?php if($gift['item']!==null&&$gift['item']!==''):?><span>Quà vật phẩm</span><?php endif;?></div><div class="lp-gift-code-line"><code><?=kp_e($gift['giftcode'])?></code><button type="button" data-gift-code="<?=kp_e($gift['giftcode'])?>">Sao chép</button></div></div></article><?php endforeach;?></div><?php else:?><div class="lp-empty-state" data-landing-reveal><span>✦</span><div><h3>Kho quà đang được làm mới</h3><p>Chưa có giftcode công khai. Mã mới sẽ tự xuất hiện tại đây khi quản trị viên mở.</p></div></div><?php endif;?>
